program.# The query buttons on their panel. Each:
# Užklausų mygtukai jų skydelyje. Kiekvienas siunčia ekrano kopiją į „Google“:
#   name: mygtuko patarimas;
#   mode: kur keliauja ekrano kopija:
#     "ai": „Google“ DI žodžiais atsako į mini raginimą virš savo rezultatų pagal
#       vaizdą ir klausimą;
#     "chat": pats DI režimas (google.com/ai) programos lange: programa įdeda ten
#       ekrano kopiją ir klausimą ir juos išsiunčia; langas atsiranda šalia pažymėtos
#       srities tik su pokalbiu ir kito klausimo lauku; laikomas mygtukas vietoj
#       mini raginimo užduoda jūsų klausimą balsu, kol jį laikote;
#     "answer": tas pats, bet langas paslėptas: atsakymas rodomas kortelėje šalia
#       pažymėtos srities;
#     "images": paieška pagal vaizdą be klausimo, programos lange šalia pažymėtos srities:
#       iš karto tikslūs atitikmenys – puslapiai su būtent šiuo vaizdu, kurių pavadinimuose
#       dažnai nurodyta, kas jame yra;
#   prompt: mini raginimas, klausimas DI, skirtas "ai", "chat" ir "answer";
#   key: mygtuko klavišas, kol ekranas užšaldytas;
#   icon: "google", "translate", "images" arba "question".
# DI mygtukai skydelyje stovi pirmi, paieška pagal vaizdą – po jų.
# Prie „Google“ prisijungiama programos lange iš nustatymų lango skyriaus „Google“ paskyra;
# kol niekas neprisijungęs, programa pasileisdama pasiūlo prisijungti.
